// Reads a file from argv[1] (or stdin) and feeds bytes to the fuzzer logic.
#include <assimp/cimport.h>
#include <assimp/Importer.hpp>
#include <assimp/Exporter.hpp>
#include <assimp/scene.h>
#include <assimp/postprocess.h>
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <string>

using namespace Assimp;

static int run(const uint8_t *data, size_t dataSize) {
    Importer importer;
    unsigned int flags = aiProcessPreset_TargetRealtime_Quality | aiProcess_ValidateDataStructure;
    const aiScene *sc = importer.ReadFileFromMemory(data, dataSize, flags, nullptr);
    if (sc == nullptr) {
        return 0;
    }
    Exporter exporter;
    exporter.ExportToBlob(sc, "fbx");
    return 0;
}

int main(int argc, char **argv) {
    std::vector<uint8_t> buf;
    if (argc > 1) {
        FILE *f = fopen(argv[1], "rb");
        if (!f) { fprintf(stderr, "cannot open %s\n", argv[1]); return 1; }
        fseek(f, 0, SEEK_END);
        long sz = ftell(f);
        fseek(f, 0, SEEK_SET);
        buf.resize(sz);
        if (sz > 0) fread(buf.data(), 1, sz, f);
        fclose(f);
    } else {
        uint8_t tmp[65536];
        size_t n;
        while ((n = fread(tmp, 1, sizeof(tmp), stdin)) > 0) {
            buf.insert(buf.end(), tmp, tmp + n);
        }
    }
    fprintf(stderr, "[harness] input size=%zu\n", buf.size());
    return run(buf.data(), buf.size());
}
"}

